VALUES ('doc-09-mitre-attack-p0-11469', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-09T14:57:15.636Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ember Bear](https://attack.mitre.org/groups/G1003) is associated with [WhisperGate](https://attack.mitre.org/software/S0689) use against multiple victims in Ukraine.(Citation: Cadet Blizzard emerges as novel threat actor)(Citation: CrowdStrike Ember Bear Profile March 2022)(Citation: Mandiant UNC2589 March 2022)", "external_references": [{"description": "CrowdStrike. (2022, March 30). Who is EMBER BEAR?. Retrieved June 9, 2022.", "source_name": "CrowdStrike Ember Bear Profile March 2022", "url": "https://www.crowdstrike.com/blog/who-is-ember-bear/"}, {"description": "Microsoft Threat Intelligence. (2023, June 14). Cadet Blizzard emerges as a novel and distinct Russian threat actor. Retrieved July 10, 2023.", "source_name": "Cadet Blizzard emerges as novel threat actor", "url": "https://www.microsoft.com/en-us/security/blog/2023/06/14/cadet-blizzard-emerges-as-a-novel-and-distinct-russian-threat-actor/"}, {"description": "Sadowski, J; Hall, R. (2022, March 4). Responses to Russia''s Invasion of Ukraine Likely to Spur Retaliation. Retrieved June 9, 2022.", "source_name": "Mandiant UNC2589 March 2022", "url": "https://www.mandiant.com/resources/russia-invasion-ukraine-retaliation"}], "id": "relationship--a9200a4f-271b-4b13-864b-a3e21de3c9f2", "modified": "2026-07-31T18:48:13.413Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--a7f57cc1-4540-4429-823f-f4e56b8473c9", "spec_version": "2.1", "target_ref": "malware--49fee0b0-390e-4bde-97f8-97ed46bd19b7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-1146