VALUES ('doc-09-mitre-attack-p0-11473', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-09-06T22:00:25.123Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Ember Bear](https://attack.mitre.org/groups/G1003) has used [PsExec](https://attack.mitre.org/software/S0029) through frameworks such as [Impacket](https://attack.mitre.org/software/S0357) for remote command execution.(Citation: CISA GRU29155 2024)", "external_references": [{"description": "US Cybersecurity & Infrastructure Security Agency et al. (2024, September 5). Russian Military Cyber Actors Target U.S. and Global Critical Infrastructure. Retrieved September 6, 2024.", "source_name": "CISA GRU29155 2024", "url": "https://www.cisa.gov/sites/default/files/2024-09/aa24-249a-russian-military-cyber-actors-target-us-and-global-critical-infrastructure.pdf"}], "id": "relationship--c2384bea-763a-4782-ba88-15a75d83f61b", "modified": "2026-07-31T18:48:13.505Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--a7f57cc1-4540-4429-823f-f4e56b8473c9", "spec_version": "2.1", "target_ref": "tool--ff6caf67-ea1f-4895-b80e-4bb0fc31c6db", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11473', 0, 79, '09-mitre-attack', 'retrieved', 'C4A40AF052DB96D2A378D29E55912EC73559F3021C9DBD94C4666A2CA8DC85EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
