VALUES ('doc-09-mitre-attack-p0-11618', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:10:41.957Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) used [NBTscan](https://attack.mitre.org/software/S0590) to scan victim networks for existing and accessible hosts.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--0a23a684-c5e4-4ef1-8eb3-f55024cc71d5", "modified": "2026-07-31T18:48:14.479Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "tool--b63970b7-ddfb-4aee-97b1-80d335e033a8", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11618', 0, 80, '09-mitre-attack', 'retrieved', '329E61E99B0653D7C5D58E6C87CE914E7A06FA9C80AC84025D2D95BF82AEA487', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
