VALUES ('doc-09-mitre-attack-p0-11619', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:11:36.496Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) used the tool [NBTscan](https://attack.mitre.org/software/S0590) to scan for remote, accessible hosts in victim environments.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--22ece51b-ebfa-474d-8a6e-6835ff891890", "modified": "2026-07-31T18:48:14.499Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11619', 0, 82, '09-mitre-attack', 'retrieved', '3ADB8BED4C65094D6A6C7B8248AE5D1B1958FABE4D0C981ED2FB2A3E03A2F376', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
