VALUES ('doc-09-mitre-attack-p0-11620', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:13:49.553Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) used [Mimikatz](https://attack.mitre.org/software/S0002) to dump credentials from LSASS memory.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--243278fe-4f59-42f8-8c39-85a7d64f0fb1", "modified": "2026-07-31T18:48:14.522Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "tool--afc079f3-c0ea-4096-b75d-3f05338b7f60", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11620', 0, 77, '09-mitre-attack', 'retrieved', '4AF929EFE8B2D96BB2F63AED3B0FA8AC5F26DA4D086637A142822436E1DA4844', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
