VALUES ('doc-09-mitre-attack-p0-11627', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T22:23:54.178Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) gathered data from database and other critical servers in victim environments, then used wiping mechanisms as an anti-analysis and anti-forensics mechanism.(Citation: Unit42 Agrius 2023)", "external_references": [{"description": "Or Chechik, Tom Fakterman, Daniel Frank & Assaf Dahan. (2023, November 6). Agonizing Serpens (Aka Agrius) Targeting the Israeli Higher Education and Tech Sectors. Retrieved May 22, 2024.", "source_name": "Unit42 Agrius 2023", "url": "https://unit42.paloaltonetworks.com/agonizing-serpens-targets-israeli-tech-higher-ed-sectors/"}], "id": "relationship--436bc39f-a6a0-4f8c-87e8-887cef2c67cd", "modified": "2026-07-31T18:48:14.653Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "attack-pattern--3c4a2599-71ee-4405-ba1e-0e28414b4bc5", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11627', 0, 90, '09-mitre-attack', 'retrieved', '698434C104B1B65FD94D8CCB056E5527B1F5EDD7CF9882B5C3303922D00918FA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
