VALUES ('doc-09-mitre-attack-p0-11628', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T19:07:25.564Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) typically uses commercial VPN services for anonymizing last-hop traffic to victim networks, such as ProtonVPN.(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--4875a71a-5600-49b2-bd30-0927db99b536", "modified": "2026-07-31T18:48:14.665Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "attack-pattern--0458aab9-ad42-4eac-9e22-706a95bafee2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11628', 0, 75, '09-mitre-attack', 'retrieved', 'CE30C858590E8AD03D4EAA2035E1C51BC9A563E37CC691E6F8FFADC755E16B28', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
