VALUES ('doc-09-mitre-attack-p0-11629', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T23:06:35.230Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Moneybird](https://attack.mitre.org/software/S1137) is associated with ransomware operations launched by [Agrius](https://attack.mitre.org/groups/G1030).(Citation: CheckPoint Agrius 2023)", "external_references": [{"description": "Marc Salinas Fernandez & Jiri Vinopal. (2023, May 23). AGRIUS DEPLOYS MONEYBIRD IN TARGETED ATTACKS AGAINST ISRAELI ORGANIZATIONS. Retrieved May 21, 2024.", "source_name": "CheckPoint Agrius 2023", "url": "https://research.checkpoint.com/2023/agrius-deploys-moneybird-in-targeted-attacks-against-israeli-organizations/"}], "id": "relationship--49257f1f-6ef2-4688-bca0-9f2cd86c9d39", "modified": "2026-07-31T18:48:14.688Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "malware--47ab6350-054f-4754-ba4d-e52a4e8751e2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11629', 0, 71, '09-mitre-attack', 'retrieved', '46929D5595D79CCD4735D623DBF4E3A5168268DE7E25D7B25CD0C7291C105642', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
