VALUES ('doc-09-mitre-attack-p0-11645', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2024-05-22T19:06:12.488Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Agrius](https://attack.mitre.org/groups/G1030) relies on web shells for persistent access post exploitation, with an emphasis on variants of [ASPXSpy](https://attack.mitre.org/software/S0073).(Citation: SentinelOne Agrius 2021)", "external_references": [{"description": "Amitai Ben & Shushan Ehrlich. (2021, May). From Wiper to Ransomware: The Evolution of Agrius. Retrieved May 21, 2024.", "source_name": "SentinelOne Agrius 2021", "url": "https://assets.sentinelone.com/sentinellabs/evol-agrius"}], "id": "relationship--c20e28d7-f577-419b-bf3f-a5d585e1f0f4", "modified": "2026-07-31T18:48:14.981Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--b8137919-38cb-4db0-90f3-437be885faba", "spec_version": "2.1", "target_ref": "malware--56f46b17-8cfa-46c0-b501-dd52fef394e2", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11645', 0, 76, '09-mitre-attack', 'retrieved', 'AB89C847B988878FAB4E0DFEC7EC10E5F1216B51D92C5A8FF64DD6988B431618', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
