VALUES ('doc-09-mitre-attack-p0-11652', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-29T20:21:33.238Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Water Galura](https://attack.mitre.org/groups/G1050) maintains a [Tor](https://attack.mitre.org/software/S0183)-hosted data leaks site for [Qilin](https://attack.mitre.org/software/S1242) ransomware and affiliates.(Citation: BushidoToken Qilin RaaS JUN 2024)(Citation: Sophos Qilin MSP APR 2025)", "external_references": [{"description": "Bradshaw, A. et al. (2025, April 1). Qilin affiliates spear-phish MSP ScreenConnect admin, targeting customers downstream. Retrieved September 26, 2025.", "source_name": "Sophos Qilin MSP APR 2025", "url": "https://news.sophos.com/en-us/2025/04/01/sophos-mdr-tracks-ongoing-campaign-by-qilin-affiliates-targeting-screenconnect/"}, {"description": "Thomas, W. (2024, June 12). Tracking Adversaries: The Qilin RaaS. Retrieved September 26, 2025.", "source_name": "BushidoToken Qilin RaaS JUN 2024", "url": "https://blog.bushidotoken.net/2024/06/tracking-adversaries-qilin-raas.html"}], "id": "relationship--c77168a4-5298-4f33-9462-008f9487d49c", "modified": "2026-07-31T18:48:14.937Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--be8847e0-9512-45db-895e-f871ab6d3820", "spec_version": "2.1", "target_ref": "tool--ed7d0cb1-87a6-43b4-9f46-ef1bc56d6c68", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11652', 0, 105, '09-mitre-attack', 'retrieved', 'BB7A14935FCDF6FC9A99FC9CB0309CBB5F7F8FBFA7BC2D14E7629392D7946BDD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
