VALUES ('doc-09-mitre-attack-p0-11653', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-09-29T20:13:08.359Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": " [Water Galura](https://attack.mitre.org/groups/G1050) has extorted victims for ransomware decryption keys and to prevent publication of data exfiltrated to their [Tor](https://attack.mitre.org/software/S0183) data leak site.(Citation: BushidoToken Qilin RaaS JUN 2024)(Citation: HC3 Qilin Threat Profile JUN 2024)\n\n", "external_references": [{"description": "Health Sector Cybersecurity Coordination Center. (2024, June 18). Qilin, aka Agenda Ransomware. Retrieved September 26, 2025.", "source_name": "HC3 Qilin Threat Profile JUN 2024", "url": "https://www.aha.org/system/files/media/file/2024/06/tlp-clear-hc3-threat-profile-qilin-aka-agenda-ransomware-6-18-2024.pdf"}, {"description": "Thomas, W. (2024, June 12). Tracking Adversaries: The Qilin RaaS. Retrieved September 26, 2025.", "source_name": "BushidoToken Qilin RaaS JUN 2024", "url": "https://blog.bushidotoken.net/2024/06/tracking-adversaries-qilin-raas.html"}], "id": "relationship--e2029939-dcf2-4211-8485-1065bf6a4c4f", "modified": "2026-07-31T18:48:14.957Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--be8847e0-9512-45db-895e-f871ab6d3820", "spec_version": "2.1", "target_ref": "attack-pattern--851e071f-208d-4c79-adc6-5974c85c78f3", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11653', 0, 113, '09-mitre-attack', 'retrieved', '1A7D5A4F3E3B2C3A881BAA646A72E498892F1970B4C642E7C106A49DEEF21F98', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
