VALUES ('doc-09-mitre-attack-p0-11662', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.038Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT28](https://attack.mitre.org/groups/G0007) has performed timestomping on victim files.(Citation: Crowdstrike DNC June 2016)", "external_references": [{"description": "Alperovitch, D.. (2016, June 15). Bears in the Midst: Intrusion into the Democratic National Committee. Retrieved August 3, 2016.", "source_name": "Crowdstrike DNC June 2016", "url": "https://www.crowdstrike.com/blog/bears-midst-intrusion-democratic-national-committee/"}], "id": "relationship--1036833a-1d4c-4d9e-b716-1e52606ab684", "modified": "2026-07-31T20:48:44.396Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "attack-pattern--47f2d673-ca62-47e9-929b-1b0be9657611", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11662', 0, 68, '09-mitre-attack', 'retrieved', '4E0A97318762DAACB5EEACB3E498F1017887DB782B46D323BC75A5D6C84A800E', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
