VALUES ('doc-09-mitre-attack-p0-11692', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-12-14T16:46:06.044Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "An [APT28](https://attack.mitre.org/groups/G0007) loader Trojan will enumerate the victim''s processes searching for explorer.exe if its current process does not have necessary permissions.(Citation: Unit 42 Playbook Dec 2017)", "external_references": [{"description": "Unit 42. (2017, December 15). Unit 42 Playbook Viewer. Retrieved December 20, 2017.", "source_name": "Unit 42 Playbook Dec 2017", "url": "https://web.archive.org/web/20230702043312/https://pan-unit42.github.io/playbook_viewer/"}], "id": "relationship--51d06864-d5de-4286-b2bb-561a8d2c4d49", "modified": "2026-07-31T20:48:44.646Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "attack-pattern--8f4a33ec-8b1f-4b80-a2f6-642b2e479580", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11692', 0, 78, '09-mitre-attack', 'retrieved', 'C2E36165D6E5C4A4F081D249A3534FED48003B1A738BF2B9837CAA00FB832D79', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
