VALUES ('doc-09-mitre-attack-p0-11695', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-01-13T21:54:29.677Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT28](https://attack.mitre.org/groups/G0007) has performed large-scale scans in an attempt to find vulnerable servers.(Citation: TrendMicro Pawn Storm 2019)", "external_references": [{"description": "Hacquebord, F. (n.d.). Pawn Storm in 2019 A Year of Scanning and Credential Phishing on High-Profile Targets. Retrieved December 29, 2020.", "source_name": "TrendMicro Pawn Storm 2019", "url": "https://documents.trendmicro.com/assets/white_papers/wp-pawn-storm-in-2019.pdf"}], "id": "relationship--54b73912-002f-43ca-b8a2-7439aff45aab", "modified": "2026-07-31T20:48:44.669Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "attack-pattern--5502c4e9-24ef-4d5f-8ee9-9e906c2f82c4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11695', 0, 75, '09-mitre-attack', 'retrieved', 'D98CE358A082D74303CD7C7FA2C8644EFEC026596F6A42DB128FFB0F89606180', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
