VALUES ('doc-09-mitre-attack-p0-11697', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "Once [APT28](https://attack.mitre.org/groups/G0007) gained access to the DCCC network, the group then proceeded to use that access to compromise the DNC network.(Citation: DOJ GRU Indictment Jul 2018)", "external_references": [{"description": "Mueller, R. (2018, July 13). Indictment - United States of America vs. VIKTOR BORISOVICH NETYKSHO, et al. Retrieved November 17, 2024.", "source_name": "DOJ GRU Indictment Jul 2018", "url": "https://cdn.cnn.com/cnn/2018/images/07/13/gru.indictment.pdf"}], "id": "relationship--565d2d07-0e2e-44e5-bc37-5a64e49394ee", "modified": "2026-07-31T20:48:44.684Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "attack-pattern--9fa07bef-9c81-421e-a8e5-ad4366c5a925", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11697', 0, 86, '09-mitre-attack', 'retrieved', 'B11EF28A78A3B35C1707BAC1CA91E8DFB37CB3B48141B673A0FE7F04377CE810', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
