VALUES ('doc-09-mitre-attack-p0-11726', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-02-25T17:34:03.352Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "(Citation: Nearest Neighbor Volexity)", "external_references": [{"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "id": "relationship--8ecdf71c-41cf-454e-98cb-a2d6678d1b1c", "modified": "2026-07-31T20:48:44.921Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "tool--da66959d-9875-4fde-bfed-11111a55895e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11726', 0, 69, '09-mitre-attack', 'retrieved', '1015AE5B0069F348E49B5DAA7B1BC8144F5F2FA5916EBB958E8CC4C1A07A6AF7', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
