VALUES ('doc-09-mitre-attack-p0-11750', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2017-05-31T21:33:27.039Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT28](https://attack.mitre.org/groups/G0007) has exploited CVE-2014-4076, CVE-2015-2387, CVE-2015-1701, CVE-2017-0263, and CVE-2022-38028 to escalate privileges.(Citation: Bitdefender APT28 Dec 2015)(Citation: Microsoft SIR Vol 19)(Citation: Securelist Sofacy Feb 2018)(Citation: Nearest Neighbor Volexity)", "external_references": [{"description": "Anthe, C. et al. (2015, October 19). Microsoft Security Intelligence Report Volume 19. Retrieved December 23, 2015.", "source_name": "Microsoft SIR Vol 19", "url": "http://download.microsoft.com/download/4/4/C/44CDEF0E-7924-4787-A56A-16261691ACE3/Microsoft_Security_Intelligence_Report_Volume_19_English.pdf"}, {"description": "Bitdefender. (2015, December). APT28 Under the Scope. Retrieved February 23, 2017.", "source_name": "Bitdefender APT28 Dec 2015", "url": "https://download.bitdefender.com/resources/media/materials/white-papers/en/Bitdefender_In-depth_analysis_of_APT28%E2%80%93The_Political_Cyber-Espionage.pdf"}, {"description": "Kaspersky Lab''s Global Research & Analysis Team. (2018, February 20). A Slice of 2017 Sofacy Activity. Retrieved November 27, 2018.", "source_name": "Securelist Sofacy Feb 2018", "url": "https://securelist.com/a-slice-of-2017-sofacy-activity/83930/"}, {"description": "Koessel, Sean. Adair, Steven. Lancaster, Tom. (2024, November 22). The Nearest Neighbor Attack: How A Russian APT Weaponized Nearby Wi-Fi Networks for Covert Access. Retrieved February 25, 2025.", "source_name": "Nearest Neighbor Volexity", "url": "https://www.volexity.com/blog/2024/11/22/the-nearest-neighbor-attack-how-a-russian-apt-weaponized-nearby-wi-fi-networks-for-covert-access/"}], "id": "relationship--cce31baa-5862-4df5-806f-15aaa7410fa5", "modified": "2026-07-31T20:48:45.126Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "attack-pattern--b21c3b2d-02e6-45b1-980b-e69051040839", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11750', 0, 164, '09-mitre-attack', 'retrieved', '09B5E6AFE52BBDD793E291AFA478B687E58577AFCCC49957BE27EDE359BF4C70', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
