VALUES ('doc-09-mitre-attack-p0-11757', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-04-19T21:59:12.700Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT28](https://attack.mitre.org/groups/G0007) has tricked unwitting recipients into clicking on malicious hyperlinks within emails crafted to resemble trustworthy senders.(Citation: US District Court Indictment GRU Oct 2018)(Citation: Secureworks IRON TWILIGHT Active Measures March 2017)", "external_references": [{"description": "Brady, S . (2018, October 3). Indictment - United States vs Aleksei Sergeyevich Morenets, et al.. Retrieved October 1, 2020.", "source_name": "US District Court Indictment GRU Oct 2018", "url": "https://www.justice.gov/opa/page/file/1098481/download"}, {"description": "Secureworks CTU. (2017, March 30). IRON TWILIGHT Supports Active Measures. Retrieved February 28, 2022.", "source_name": "Secureworks IRON TWILIGHT Active Measures March 2017", "url": "https://www.secureworks.com/research/iron-twilight-supports-active-measures"}], "id": "relationship--d7af8f20-9581-4b41-a591-118842f8ba6e", "modified": "2026-07-31T20:48:45.183Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--bef4c620-0787-42a8-a96d-b7eb6e85917c", "spec_version": "2.1", "target_ref": "attack-pattern--ef67e13e-5598-4adc-bdb2-998225874fa9", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11757', 0, 117, '09-mitre-attack', 'retrieved', 'B4F6CFF836D1CE2F555B93F5CEB4340C125D7FC13D341A020248D04EA1ABED1A', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
