VALUES ('doc-09-mitre-attack-p0-11828', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2025-01-08T17:46:59.951Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT42](https://attack.mitre.org/groups/G1044) has intercepted SMS-based one-time passwords and has set up two-factor authentication.(Citation: Mandiant APT42-charms) Additionally, [APT42](https://attack.mitre.org/groups/G1044) has used cloned or fake websites to capture MFA tokens.(Citation: Mandiant APT42-untangling) ", "external_references": [{"description": "Mandiant. (n.d.). APT42: Crooked Charms, Cons and Compromises. Retrieved October 9, 2024.", "source_name": "Mandiant APT42-charms", "url": "https://services.google.com/fh/files/misc/apt42-crooked-charms-cons-and-compromises.pdf"}, {"description": "Rozmann, O., et al. (2024, May 1). Uncharmed: Untangling Iran''s APT42 Operations. Retrieved October 9, 2024.", "source_name": "Mandiant APT42-untangling", "url": "https://cloud.google.com/blog/topics/threat-intelligence/untangling-iran-apt42-operations"}], "id": "relationship--ea2bea46-e1fd-4edf-bba7-8d0552e1975f", "modified": "2026-07-31T18:48:16.524Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c0291346-defe-48d7-9542-9e074ba1bdfb", "spec_version": "2.1", "target_ref": "attack-pattern--dd43c543-bb85-4a6f-aa6e-160d90d06a49", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11828', 0, 99, '09-mitre-attack', 'retrieved', '8BB46E48A17FD630294DB0EA0DCB9AAA91AAC32BB605D3E73623303667FBCFA9', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
