VALUES ('doc-09-mitre-attack-p0-11937', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2026-04-16T14:27:06.928Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT-C-36](https://attack.mitre.org/groups/G0099) has used a customized version of [njRAT](https://attack.mitre.org/software/S0385).(Citation: Kaspersky BlindEagle AUG 2024)(Citation: Check Point Blind Eagle MAR 2025)(Citation: Recorded Future TAG-144 AUG 2025)", "external_references": [{"description": "Check Point Research. (2025, March 10). Blind Eagle: …And Justice for All. Retrieved April 16, 2026.", "source_name": "Check Point Blind Eagle MAR 2025", "url": "https://research.checkpoint.com/2025/blind-eagle-and-justice-for-all/"}, {"description": "Global Research & Analysis Team, Kaspersky. (2024, August 19). BlindEagle flying high in Latin America. Retrieved April 16, 2026.", "source_name": "Kaspersky BlindEagle AUG 2024", "url": "https://securelist.com/blindeagle-apt/113414/"}, {"description": "Insikt Group. (2025, August 26). TAG-144’s Persistent Grip on South American Organizations. Retrieved April 16, 2026.", "source_name": "Recorded Future TAG-144 AUG 2025", "url": "https://assets.recordedfuture.com/insikt-report-pdfs/2025/cta-2025-0826.pdf"}], "id": "relationship--00c26d3c-72ba-4197-acd1-690691d452aa", "modified": "2026-07-31T18:48:18.310Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c4d50cdf-87ce-407d-86d8-862883485842", "spec_version": "2.1", "target_ref": "malware--d906e6f7-434c-44c0-b51a-ed50af8f7945", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11937', 0, 131, '09-mitre-attack', 'retrieved', 'FED2DBA927ABD9E061B2597F0B1C00BB1DEECF3757D47C41060EF7386583B945', 'v1', '{"source_id"