VALUES ('doc-09-mitre-attack-p0-11939', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-05-05T19:37:33.769Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT-C-36](https://attack.mitre.org/groups/G0099) has prompted victims to open attachments and to accept macros in order to execute the subsequent payload.(Citation: QiAnXin APT-C-36 Feb2019)(Citation: Recorded Future TAG-144 AUG 2025) [APT-C-36](https://attack.mitre.org/groups/G0099) has also lured victims into opening malicious files hosted on Google Drive that triggered WebDAV requests to download malware.(Citation: Check Point Blind Eagle MAR 2025)(Citation: Zscaler BlindEagle DEC 2025)", "external_references": [{"description": "Check Point Research. (2025, March 10). Blind Eagle: …And Justice for All. Retrieved April 16, 2026.", "source_name": "Check Point Blind Eagle MAR 2025", "url": "https://research.checkpoint.com/2025/blind-eagle-and-justice-for-all/"}, {"description": "Insikt Group. (2025, August 26). TAG-144’s Persistent Grip on South American Organizations. Retrieved April 16, 2026.", "source_name": "Recorded Future TAG-144 AUG 2025", "url": "https://assets.recordedfuture.com/insikt-report-pdfs/2025/cta-2025-0826.pdf"}, {"description": "Pellegrino, G. (2025, December 16). BlindEagle Targets Colombian Government Agency with Caminho and DCRAT. Retrieved April 16, 2026.", "source_name": "Zscaler BlindEagle DEC 2025", "url": "https://www.zscaler.com/blogs/security-research/blindeagle-targets-colombian-government-agency-caminho-and-dcrat"}, {"description": "QiAnXin Threat Intelligence Center. (2019, February 18). APT-C-36: Continuous Attacks Targeting Colombian Government Institutions and Corporations. Retrieved May 5, 2020.", "source_name": "QiAnXin APT-C-36 Feb2019", "url": "https://web.archive.org/web/20190625182633if_/https://ti.360.net/blog/articles/apt-c-36-continuous-attacks-targeting-colombian-government-institutions-and-corporations-en/"}], "id": "relationship--20599767-204a-4cbf-ada7-0f931ee925e4", "modified": "2026-07-31T18:48:18.344Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c4d50cdf-87ce-407d-86d8-862883485842", "spec_version": "2.1", "target_ref": "attack-pattern--232b7f21-adf9-4b42-b936-b9d6f7df856e", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11939', 0, 190, '09-mitre-attack', 'retrieved', '00B17852E798081EE1148011CE0D2A70FEE9B0F2F0E850DCE26AD8066E8DDEDC', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
