VALUES ('doc-09-mitre-attack-p0-11954', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-05-26T20:17:53.337Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[APT-C-36](https://attack.mitre.org/groups/G0099) utilizes tools well known in crime communities and has obtained and used a modified variant of [Imminent Monitor](https://attack.mitre.org/software/S0434).(Citation: QiAnXin APT-C-36 Feb2019)(Citation: Check Point Blind Eagle MAR 2025)", "external_references": [{"description": "Check Point Research. (2025, March 10). Blind Eagle: …And Justice for All. Retrieved April 16, 2026.", "source_name": "Check Point Blind Eagle MAR 2025", "url": "https://research.checkpoint.com/2025/blind-eagle-and-justice-for-all/"}, {"description": "QiAnXin Threat Intelligence Center. (2019, February 18). APT-C-36: Continuous Attacks Targeting Colombian Government Institutions and Corporations. Retrieved May 5, 2020.", "source_name": "QiAnXin APT-C-36 Feb2019", "url": "https://web.archive.org/web/20190625182633if_/https://ti.360.net/blog/articles/apt-c-36-continuous-attacks-targeting-colombian-government-institutions-and-corporations-en/"}], "id": "relationship--6c89f28c-963b-44ef-8dda-5916aa17b7e9", "modified": "2026-07-31T18:48:18.542Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c4d50cdf-87ce-407d-86d8-862883485842", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-11954', 0, 111, '09-mitre-attack', 'retrieved', '5E0F920C9F618A6D37126FB28E196D8C89D12BDF02C97A98013A99763236A433', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_ob