VALUES ('doc-09-mitre-attack-p0-12048', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-12T16:59:08.082Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has used a custom secure delete function to overwrite file contents with data from heap memory.(Citation: Novetta Blockbuster)", "external_references": [{"description": "Novetta Threat Research Group. (2016, February 24). Operation Blockbuster: Unraveling the Long Thread of the Sony Attack. Retrieved February 25, 2016.", "source_name": "Novetta Blockbuster", "url": "https://web.archive.org/web/20160226161828/https://www.operationblockbuster.com/wp-content/uploads/2016/02/Operation-Blockbuster-Report.pdf"}], "id": "relationship--27323a25-ef80-4519-b934-19f5ff090c70", "modified": "2026-07-31T20:48:46.516Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--d45a3d09-b3cf-48f4-9f0f-f521ee5cb05c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12048', 0, 77, '09-mitre-attack', 'retrieved', '1033A08AD4623284ED298163CB987CA9E4FABE3CB82BB5D0C6164C1CF30DB299', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
