VALUES ('doc-09-mitre-attack-p0-12065', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2021-03-01T20:37:05.855Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has obtained SSL certificates for their C2 domains.(Citation: CISA AppleJeus Feb 2021)", "external_references": [{"description": "Cybersecurity and Infrastructure Security Agency. (2021, February 21). AppleJeus: Analysis of North Korea’s Cryptocurrency Malware. Retrieved March 1, 2021.", "source_name": "CISA AppleJeus Feb 2021", "url": "https://us-cert.cisa.gov/ncas/alerts/aa21-048a"}], "id": "relationship--41c193c1-8269-4a2e-9ed8-9dd51489a03f", "modified": "2026-07-31T20:48:46.659Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--19401639-28d0-4c3c-adcc-bc2ba22f6421", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12065', 0, 71, '09-mitre-attack', 'retrieved', 'CF0572FF9B0EA08F3A41D184C05026553B9BB1EF3D26B51F1391BB6515C8D6A0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
