VALUES ('doc-09-mitre-attack-p0-12075', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-01T15:24:06.895Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has sent malicious links to victims via email.(Citation: Kaspersky ThreatNeedle Feb 2021)", "external_references": [{"description": "Vyacheslav Kopeytsev and Seongsu Park. (2021, February 25). Lazarus targets defense industry with ThreatNeedle. Retrieved October 27, 2021.", "source_name": "Kaspersky ThreatNeedle Feb 2021", "url": "https://securelist.com/lazarus-threatneedle/100803/"}], "id": "relationship--5e28da21-d977-4488-a8dc-10bad0833374", "modified": "2026-07-31T20:48:46.746Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--2b742742-28c3-4e1b-bab7-8350d6300fa7", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12075', 0, 70, '09-mitre-attack', 'retrieved', '70C32438BCB3BEB004A2B7AE4C0F979296FE646183AFBA2CA0255EA1BC2B90EE', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
