VALUES ('doc-09-mitre-attack-p0-12079', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-23T16:57:13.567Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has renamed system utilities such as wscript.exe and mshta.exe .(Citation: Qualys LolZarus)", "external_references": [{"description": "Pradhan, A. (2022, February 8). LolZarus: Lazarus Group Incorporating Lolbins into Campaigns. Retrieved March 22, 2022.", "source_name": "Qualys LolZarus", "url": "https://blog.qualys.com/vulnerabilities-threat-research/2022/02/08/lolzarus-lazarus-group-incorporating-lolbins-into-campaigns"}], "id": "relationship--6441d8c3-861f-4ce3-9121-809d2b0d173b", "modified": "2026-07-31T20:48:46.776Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--bd5b58a4-a52d-4a29-bc0d-3f1d3968eb6b", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12079', 0, 66, '09-mitre-attack', 'retrieved', '4D79B15369FE3D7AFFFD07269C65C1401E450C6A570DAE8B36D8FE85AEA5C62B', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
