VALUES ('doc-09-mitre-attack-p0-12091', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-02-01T16:00:17.307Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has obtained a variety of tools for their operations, including [Responder](https://attack.mitre.org/software/S0174) and PuTTy PSCP.(Citation: Kaspersky ThreatNeedle Feb 2021)", "external_references": [{"description": "Vyacheslav Kopeytsev and Seongsu Park. (2021, February 25). Lazarus targets defense industry with ThreatNeedle. Retrieved October 27, 2021.", "source_name": "Kaspersky ThreatNeedle Feb 2021", "url": "https://securelist.com/lazarus-threatneedle/100803/"}], "id": "relationship--7b2e912e-4561-4edc-87fe-11f9e259a5a9", "modified": "2026-07-31T20:48:46.872Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--a2fdce72-04b2-409a-ac10-cc1695f4fce0", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12091', 0, 76, '09-mitre-attack', 'retrieved', '779B5E67F18EC7251EDCCDCC88DDDBD4E69F2899A4B7C1F94B86E32BC899F5D4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
