VALUES ('doc-09-mitre-attack-p0-12100', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) delivered [RATANKBA](https://attack.mitre.org/software/S0241) and other malicious code to victims via a compromised legitimate website.(Citation: RATANKBA)(Citation: Google TAG Lazarus Jan 2021)", "external_references": [{"description": "Trend Micro. (2017, February 27). RATANKBA: Delving into Large-scale Watering Holes against Enterprises. Retrieved May 22, 2018.", "source_name": "RATANKBA", "url": "https://www.trendmicro.com/en_us/research/17/b/ratankba-watering-holes-against-enterprises.html"}, {"description": "Weidemann, A. (2021, January 25). New campaign targeting security researchers. Retrieved December 20, 2021.", "source_name": "Google TAG Lazarus Jan 2021", "url": "https://blog.google/threat-analysis-group/new-campaign-targeting-security-researchers/"}], "id": "relationship--829f88fc-453a-40d1-8566-90dfe0934173", "modified": "2026-07-31T20:48:46.942Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--d742a578-d70e-4d0e-96a6-02a9c30204e6", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12100', 0, 96, '09-mitre-attack', 'retrieved', 'DBE013A3A765B26B48B444F1E08E3236E0F9181B0C45C9CB13B2227E3AA3AAE3', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
