VALUES ('doc-09-mitre-attack-p0-12108', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-08-23T15:30:27.147Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has used a custom hashing method to resolve APIs used in shellcode.(Citation: Lazarus APT January 2022)", "external_references": [{"description": "Saini, A. and Hossein, J. (2022, January 27). North Korea’s Lazarus APT leverages Windows Update client, GitHub in latest campaign. Retrieved January 27, 2022.", "source_name": "Lazarus APT January 2022", "url": "https://blog.malwarebytes.com/threat-intelligence/2022/01/north-koreas-lazarus-apt-leverages-windows-update-client-github-in-latest-campaign/"}], "id": "relationship--939b7c8a-3a2a-43a7-82e2-55f3b62c15da", "modified": "2026-07-31T20:48:47.005Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--ea4c2f9c-9df1-477c-8c42-6da1118f2ac4", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12108', 0, 80, '09-mitre-attack', 'retrieved', 'C99ADBCB88E758E4FC849B02D06A050C6F56B3C57F860025128B2B80A47CB5BD', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
