VALUES ('doc-09-mitre-attack-p0-12131', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-04-13T15:57:57.700Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has used a scheduled task named `SRCheck` to mask the execution of a malicious .dll.(Citation: ESET Twitter Ida Pro Nov 2021)", "external_references": [{"description": "Cherepanov, Anton. (2019, November 10). ESETresearch discovered a trojanized IDA Pro installer. Retrieved September 12, 2024.", "source_name": "ESET Twitter Ida Pro Nov 2021", "url": "https://x.com/ESETresearch/status/1458438155149922312"}], "id": "relationship--d29db5f7-25cb-49e3-81da-04263e32b65c", "modified": "2026-07-31T20:48:47.192Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--7bdca9d5-d500-4d7d-8c52-5fd47baf4c0c", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12131', 0, 79, '09-mitre-attack', 'retrieved', 'E65E96FEDA29DD8732A59674950DF9D102CDF07BF161A0BD52507982BC3D29E2', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
