VALUES ('doc-09-mitre-attack-p0-12135', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-03-02T17:32:03.501Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Lazarus Group](https://attack.mitre.org/groups/G0032) has replaced `win_fw.dll`, an internal component that is executed during IDA Pro installation, with a malicious DLL to download and execute a payload.(Citation: ESET Twitter Ida Pro Nov 2021) [Lazarus Group](https://attack.mitre.org/groups/G0032) utilized DLL side-loading to execute malicious payloads through abuse of the legitimate processes `wsmprovhost.exe` and `dfrgui.exe`.(Citation: ASEC Lazarus 2022)", "external_references": [{"description": "AhnLab ASEC. (2022, October 6). Lazarus Group Uses the DLL Side-Loading Technique (mi.dll). Retrieved January 7, 2025.", "source_name": "ASEC Lazarus 2022", "url": "https://asec.ahnlab.com/en/39828/"}, {"description": "Cherepanov, Anton. (2019, November 10). ESETresearch discovered a trojanized IDA Pro installer. Retrieved September 12, 2024.", "source_name": "ESET Twitter Ida Pro Nov 2021", "url": "https://x.com/ESETresearch/status/1458438155149922312"}], "id": "relationship--daf75556-254a-41af-960d-5b1012c739e3", "modified": "2026-07-31T20:48:47.221Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--c93fccb1-e8e8-42cf-ae33-2ad1d183913a", "spec_version": "2.1", "target_ref": "attack-pattern--2fee9321-3e71-4cf4-af24-d4d40d355b34", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12135', 0, 132, '09-mitre-attack', 'retrieved', '91CEC3B8D16E034416321787C3D4362815BCCD8889CBEC4C3C483A9B3FC67162', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": 