VALUES ('doc-09-mitre-attack-p0-12188', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-07-18T20:16:08.155Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Earth Lusca](https://attack.mitre.org/groups/G1006) used the command powershell “Get-EventLog -LogName security -Newest 500 | where {$_.EventID -eq 4624} | format-list -\nproperty * | findstr “Address”” to find the network information of successfully logged-in accounts to discovery addresses of other machines. [Earth Lusca](https://attack.mitre.org/groups/G1006) has also used multiple scanning tools to discover other machines within the same compromised network.(Citation: TrendMicro EarthLusca 2022)", "external_references": [{"description": "Chen, J., et al. (2022). Delving Deep: An Analysis of Earth Lusca’s Operations. Retrieved July 1, 2022.", "source_name": "TrendMicro EarthLusca 2022", "url": "https://www.trendmicro.com/content/dam/trendmicro/global/en/research/22/a/earth-lusca-employs-sophisticated-infrastructure-varied-tools-and-techniques/technical-brief-delving-deep-an-analysis-of-earth-lusca-operations.pdf"}], "id": "relationship--2bb7ed69-8f59-47f3-8d86-f1c1202c7629", "modified": "2026-07-31T20:48:48.151Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--cc613a49-9bfa-4e22-98d1-15ffbb03f034", "spec_version": "2.1", "target_ref": "attack-pattern--e358d692-23c0-4a31-9eb6-ecc13a8d7735", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12188', 0, 112, '09-mitre-attack', 'retrieved', 'C87672B998BBCA98341A081F595DBEB1F03EC9DB2EFC545B200FEAC9FE022CA0', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
