VALUES ('doc-09-mitre-attack-p0-12197', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-09-09T15:57:19.550Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Earth Lusca](https://attack.mitre.org/groups/G1006) has added the Registry key `HKLM\\SYSTEM\\ControlSet001\\Control\\Print\\Environments\\Windows x64\\Print Processors\\UDPrint” /v Driver /d “spool.dll /f` to load malware as a Print Processor.(Citation: TrendMicro EarthLusca 2022)", "external_references": [{"description": "Chen, J., et al. (2022). Delving Deep: An Analysis of Earth Lusca’s Operations. Retrieved July 1, 2022.", "source_name": "TrendMicro EarthLusca 2022", "url": "https://www.trendmicro.com/content/dam/trendmicro/global/en/research/22/a/earth-lusca-employs-sophisticated-infrastructure-varied-tools-and-techniques/technical-brief-delving-deep-an-analysis-of-earth-lusca-operations.pdf"}], "id": "relationship--6a779cbf-ef5c-4018-a91f-10889b2068b0", "modified": "2026-07-31T20:48:48.222Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--cc613a49-9bfa-4e22-98d1-15ffbb03f034", "spec_version": "2.1", "target_ref": "attack-pattern--2de47683-f398-448f-b947-9abcc3e32fad", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12197', 0, 79, '09-mitre-attack', 'retrieved', '81EFC56C2C8396B1D230B20CCAE3F2F7833A5E22E35EE9980D6A2190A6AEB904', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
