VALUES ('doc-09-mitre-attack-p0-12244', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2019-04-18T20:13:56.028Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[FIN4](https://attack.mitre.org/groups/G0085) has created rules in victims'' Microsoft Outlook accounts to automatically delete emails containing words such as “hacked,\" \"phish,\" and “malware\" in a likely attempt to prevent organizations from communicating about their activities.(Citation: FireEye Hacking FIN4 Dec 2014)", "external_references": [{"description": "Vengerik, B. et al.. (2014, December 5). Hacking the Street? FIN4 Likely Playing the Market. Retrieved December 17, 2018.", "source_name": "FireEye Hacking FIN4 Dec 2014", "url": "https://web.archive.org/web/20220313062515/https://www.mandiant.com/sites/default/files/2021-09/rpt-fin4.pdf"}], "id": "relationship--70a17629-6b01-4764-932b-8be576270329", "modified": "2026-08-04T20:30:53.880Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--d0b3393b-3bec-4ba3-bda9-199d30db47b6", "spec_version": "2.1", "target_ref": "attack-pattern--0cf55441-b176-4332-89e7-2c4c7799d0ff", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12244', 0, 96, '09-mitre-attack', 'retrieved', 'ABA8A33772208BEFE1C9B083C004332DBB048A48C9C693A33E4926A06F91D1B4', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
