VALUES ('doc-09-mitre-attack-p0-12343', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2022-06-10T12:55:27.257Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[LAPSUS$](https://attack.mitre.org/groups/G1004) has replayed stolen session token and passwords to trigger simple-approval MFA prompts in hope of the legitimate user will grant necessary approval.(Citation: MSTIC DEV-0537 Mar 2022)", "external_references": [{"description": "MSTIC, DART, M365 Defender. (2022, March 24). DEV-0537 Criminal Actor Targeting Organizations for Data Exfiltration and Destruction. Retrieved May 17, 2022.", "source_name": "MSTIC DEV-0537 Mar 2022", "url": "https://www.microsoft.com/security/blog/2022/03/22/dev-0537-criminal-actor-targeting-organizations-for-data-exfiltration-and-destruction/"}], "id": "relationship--fc5c0e5f-b730-4396-9922-7e2e91b4a106", "modified": "2026-07-31T20:48:49.573Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--d8bc9788-4f7d-41a9-9e9d-ee1ea18a8cf7", "spec_version": "2.1", "target_ref": "attack-pattern--dd43c543-bb85-4a6f-aa6e-160d90d06a49", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12343', 0, 86, '09-mitre-attack', 'retrieved', 'A7619D044A35C98DF4FFCF53E845DBAB88AF38184D9FA33BE4208F239C1D56C1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
