VALUES ('doc-09-mitre-attack-p0-12344', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-04-18T17:59:24.739Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[BlackOasis](https://attack.mitre.org/groups/G0063)''s first stage shellcode contains a NOP sled with alternative instructions that was likely designed to bypass antivirus tools.(Citation: Securelist BlackOasis Oct 2017)", "external_references": [{"description": "Kaspersky Lab''s Global Research & Analysis Team. (2017, October 16). BlackOasis APT and new targeted attacks leveraging zero-day exploit. Retrieved February 15, 2018.", "source_name": "Securelist BlackOasis Oct 2017", "url": "https://securelist.com/blackoasis-apt-and-new-targeted-attacks-leveraging-zero-day-exploit/82732/"}], "id": "relationship--4ad9aa86-f489-4f0f-926f-f381221c3705", "modified": "2026-07-31T18:48:22.805Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--da49b9f1-ca99-443f-9728-0a074db66850", "spec_version": "2.1", "target_ref": "attack-pattern--b3d682b6-98f2-4fb0-aa3b-b4df007ca70a", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12344', 0, 84, '09-mitre-attack', 'retrieved', '1AFACB98C113E9F4714344A2B80E419D7E7215BE7D78DB5BE602DE2FCE4CAE76', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
