VALUES ('doc-09-mitre-attack-p0-12346', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Group](https://attack.mitre.org/groups/G0080) has used public sites such as github.com and sendspace.com to upload files and then download them to victim computers.(Citation: PTSecurity Cobalt Group Aug 2017)(Citation: PTSecurity Cobalt Dec 2016) The group''s JavaScript backdoor is also capable of downloading files.(Citation: Morphisec Cobalt Gang Oct 2018)", "external_references": [{"description": "Positive Technologies. (2017, August 16). Cobalt Strikes Back: An Evolving Multinational Threat to Finance. Retrieved September 5, 2018.", "source_name": "PTSecurity Cobalt Group Aug 2017", "url": "https://www.ptsecurity.com/upload/corporate/ww-en/analytics/Cobalt-2017-eng.pdf"}, {"description": "Positive Technologies. (2016, December 16). Cobalt Snatch. Retrieved October 9, 2018.", "source_name": "PTSecurity Cobalt Dec 2016", "url": "https://www.ptsecurity.com/upload/corporate/ww-en/analytics/Cobalt-Snatch-eng.pdf"}, {"description": "Gorelik, M. (2018, October 08). Cobalt Group 2.0. Retrieved November 5, 2018.", "source_name": "Morphisec Cobalt Gang Oct 2018", "url": "https://blog.morphisec.com/cobalt-gang-2.0"}], "id": "relationship--07ab4fde-e1fd-4740-863e-c40cc8722d32", "modified": "2026-07-31T18:48:22.783Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dc6fe6ee-04c2-49be-ba3d-f38d2463c02a", "spec_version": "2.1", "target_ref": "attack-pattern--e6919abc-99f9-4c6c-95a5-14761e7b2add", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12346', 0, 142, '09-mitre-attack', 'retrieved', '7883502A00AC41ACE04429366F277CE1B7B53DABAC5C98E22C6B6F7A6832E183', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
