VALUES ('doc-09-mitre-attack-p0-12347', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Group](https://attack.mitre.org/groups/G0080) obfuscated several scriptlets and code used on the victim’s machine, including through use of XOR and RC4.(Citation: Talos Cobalt Group July 2018)(Citation: Morphisec Cobalt Gang Oct 2018)", "external_references": [{"description": "Gorelik, M. (2018, October 08). Cobalt Group 2.0. Retrieved November 5, 2018.", "source_name": "Morphisec Cobalt Gang Oct 2018", "url": "https://blog.morphisec.com/cobalt-gang-2.0"}, {"description": "Svajcer, V. (2018, July 31). Multiple Cobalt Personality Disorder. Retrieved September 5, 2018.", "source_name": "Talos Cobalt Group July 2018", "url": "https://blog.talosintelligence.com/2018/07/multiple-cobalt-personality-disorder.html"}], "id": "relationship--1010f466-818d-4387-9e43-9ae5e9bf9a40", "modified": "2026-07-31T18:48:22.800Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dc6fe6ee-04c2-49be-ba3d-f38d2463c02a", "spec_version": "2.1", "target_ref": "attack-pattern--d511a6f6-4a33-41d5-bc95-c343875d1377", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12347', 0, 102, '09-mitre-attack', 'retrieved', 'F3834265B763EBBBD7CC66911CA11551B2734A2C72C6B8FF788054C749BCF9DA', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
