VALUES ('doc-09-mitre-attack-p0-12362', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2018-10-17T00:14:20.652Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Cobalt Group](https://attack.mitre.org/groups/G0080) has sent Word OLE compound documents with malicious obfuscated VBA macros that will run upon user execution.(Citation: Talos Cobalt Group July 2018)(Citation: PTSecurity Cobalt Group Aug 2017)(Citation: Group IB Cobalt Aug 2017)(Citation: Morphisec Cobalt Gang Oct 2018)(Citation: Unit 42 Cobalt Gang Oct 2018)(Citation: TrendMicro Cobalt Group Nov 2017)", "external_references": [{"description": "Svajcer, V. (2018, July 31). Multiple Cobalt Personality Disorder. Retrieved September 5, 2018.", "source_name": "Talos Cobalt Group July 2018", "url": "https://blog.talosintelligence.com/2018/07/multiple-cobalt-personality-disorder.html"}, {"description": "Positive Technologies. (2017, August 16). Cobalt Strikes Back: An Evolving Multinational Threat to Finance. Retrieved September 5, 2018.", "source_name": "PTSecurity Cobalt Group Aug 2017", "url": "https://www.ptsecurity.com/upload/corporate/ww-en/analytics/Cobalt-2017-eng.pdf"}, {"description": "Matveeva, V. (2017, August 15). Secrets of Cobalt. Retrieved October 10, 2018.", "source_name": "Group IB Cobalt Aug 2017", "url": "https://www.group-ib.com/blog/cobalt"}, {"description": "Gorelik, M. (2018, October 08). Cobalt Group 2.0. Retrieved November 5, 2018.", "source_name": "Morphisec Cobalt Gang Oct 2018", "url": "https://blog.morphisec.com/cobalt-gang-2.0"}, {"description": "Unit 42. (2018, October 25). New Techniques to Uncover and Attribute Financial actors Commodity Builders and Infrastructure Revealed. Retrieved December 11, 2018.", "source_name": "Unit 42 Cobalt Gang Oct 2018", "url": "https://researchcenter.paloaltonetworks.com/2018/10/unit42-new-techniques-uncover-attribute-cobalt-gang-commodity-builders-infrastructure-revealed/"}, {"description": "Giagone, R., Bermejo, L., and Yarochkin, F. (2017, November 20). Cobalt Strikes Again: Spam Runs Use Macros and CVE-2017-8759 Exploit Against Russian Banks. Retrieved March 7, 2019.", "source_name": "TrendMicro Cobalt Group Nov 2017", "url": "https://blog.trendmicro.com/trendlabs-security-intelligence/cobalt-spam-runs-use-macros-cve-2017-8759-exploit/"}], "id": "relationship--7d115073-c008-4394-867d-07c385d3db87", "modified": "2026-07-31T18:48:23.087Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dc6fe6ee-04c2-49be-ba3d-f38d2463c02a", "spec_version": "2.1", "target_ref": "attack-pattern--dfd7cc1d-e1d8-4394-a198-97c4cab8aa67", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12362', 0, 239, '09-mitre-attack', 'retrieved', 'D4494CF1EE1CDFCB8F73F0BFD411750D546C74EA1C0DCD5C54DCE90E3E0A9CA1', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
