VALUES ('doc-09-mitre-attack-p0-12408', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-10T16:24:47.455Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wizard Spider](https://attack.mitre.org/groups/G0102) has used SMB to drop Cobalt Strike Beacon on a domain controller for lateral movement.(Citation: DFIR Ryuk 2 Hour Speed Run November 2020)(Citation: DFIR Ryuk''s Return October 2020)", "external_references": [{"description": "The DFIR Report. (2020, November 5). Ryuk Speed Run, 2 Hours to Ransom. Retrieved November 6, 2020.", "source_name": "DFIR Ryuk 2 Hour Speed Run November 2020", "url": "https://thedfirreport.com/2020/11/05/ryuk-speed-run-2-hours-to-ransom/"}, {"description": "The DFIR Report. (2020, October 8). Ryuk’s Return. Retrieved October 9, 2020.", "source_name": "DFIR Ryuk''s Return October 2020", "url": "https://thedfirreport.com/2020/10/08/ryuks-return/"}], "id": "relationship--2bb3c950-2099-4d7d-ac13-05a1470fc3c6", "modified": "2026-07-31T20:48:50.078Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e51-bc29-71d5b4802168"], "relationship_type": "uses", "revoked": false, "source_ref": "intrusion-set--dd2d9ca6-505b-4860-a604-233685b802c7", "spec_version": "2.1", "target_ref": "attack-pattern--4f9ca633-15c5-463c-9724-bdcd54fde541", "type": "relationship", "x_mitre_attack_spec_version": "3.3.0", "x_mitre_deprecated": false, "x_mitre_modified_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5"}', 'kb-doc-09-mitre-attack-p0-12408', 0, 110, '09-mitre-attack', 'retrieved', '9D3950ECD075B239283B682DC3C13BC11DDBC05EAD519A5104E976C3B00F2C40', 'v1', '{"source_id": "09-mitre-attack", "version": "retrieved", "corpus_version": "v1", "knowledge_object_type": "STRUCTURED_DATA"}')
