VALUES ('doc-09-mitre-attack-p0-12430', 'doc-09-mitre-attack', 'STIX object', NULL, '{"created": "2020-11-10T16:04:00.973Z", "created_by_ref": "identity--c78cb6e5-0c4b-4611-8297-d1b8b55e40b5", "description": "[Wizard Spider](https://attack.mitre.org/groups/G0102) has shut down or uninstalled security applications on victim systems that might prevent ransomware from executing.(Citation: DHS/CISA Ransomware Targeting Healthcare October 2020)(Citation: FireEye KEGTAP SINGLEMALT October 2020)(Citation: DFIR Ryuk''s Return October 2020)(Citation: Mandiant FIN12 Oct 2021)", "external_references": [{"description": "DHS/CISA. (2020, October 28). Ransomware Activity Targeting the Healthcare and Public Health Sector. Retrieved October 28, 2020.", "source_name": "DHS/CISA Ransomware Targeting Healthcare October 2020", "url": "https://us-cert.cisa.gov/ncas/alerts/aa20-302a"}, {"description": "Kimberly Goody, Jeremy Kennelly, Joshua Shilko, Steve Elovitz, Douglas Bienstock. (2020, October 28). Unhappy Hour Special: KEGTAP and SINGLEMALT With a Ransomware Chaser. Retrieved October 28, 2020.", "source_name": "FireEye KEGTAP SINGLEMALT October 2020", "url": "https://www.fireeye.com/blog/threat-research/2020/10/kegtap-and-singlemalt-with-a-ransomware-chaser.html"}, {"description": "Shilko, J., et al. (2021, October 7). FIN12: The Prolific Ransomware Intrusion Threat Actor That Has Aggressively Pursued Healthcare Targets. Retrieved June 15, 2023.", "source_name": "Mandiant FIN12 Oct 2021", "url": "https://web.archive.org/web/20220313061955/https://www.mandiant.com/sites/default/files/2021-10/fin12-group-profile.pdf"}, {"description": "The DFIR Report. (2020, October 8). Ryuk’s Return. Retrieved October 9, 2020.", "source_name": "DFIR Ryuk''s Return October 2020", "url": "https://thedfirreport.com/2020/10/08/ryuks-return/"}], "id": "relationship--61a16f5b-29c2-4d75-bf4f-36228fe68016", "modified": "2026-07-31T20:48:50.244Z", "object_marking_refs": ["marking-definition--fa42a846-8d90-4e